// Controller — does NOT deadlock in Core, but starves the pool
[HttpGet("session/{id}")]
public IActionResult GetSession(string id)
{
    // Blocks a pool thread for entire Redis + HTTP latency
    var data = _service.LoadSessionAsync(id).Result;
    return Ok(data);
}

