public string GetToken(string sessionId)
{
    return FetchTokenAsync(sessionId).GetAwaiter().GetResult();
}

// GOOD — expose async surface; let caller decide
public Task<string> GetTokenAsync(string sessionId, CancellationToken ct)
    => FetchTokenAsync(sessionId, ct);

